import { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { StagecraftRoot, useMockDbVersion } from '@stagecraft/react';
import { Card, Pill, StatusBadge, tokens } from '@acme/ui';

const API = 'https://api.acme.example';
type Account = { name: string; status: string };
// `category` is not in the API contract yet (acme-api openapi.json); optional until the backend adds it.
type Payment = { id: string; vendor: string; amount: number; category?: string };
type Me = { name: string; role: string };

function useGet<T>(path: string) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState(false);
  const v = useMockDbVersion();
  useEffect(() => {
    setError(false);
    fetch(API + path)
      .then((r) => (r.ok ? r.json() : Promise.reject(r.status)))
      .then(setData)
      .catch(() => {
        setData(null);
        setError(true);
      });
  }, [path, v]);
  return { data, error };
}

function Dashboard() {
  const { data: me } = useGet<Me>('/v1/me');
  const { data: account } = useGet<Account>('/v1/account');
  const { data: payments, error: paymentsError } = useGet<Payment[]>('/v1/payments');
  return (
    <main style={{ padding: 24, maxWidth: 880 }}>
      <header style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <h1 style={{ margin: 0, flex: 1 }} data-testid="account">
          {account?.name ?? '…'} {account && <StatusBadge status={account.status} />}
        </h1>
        <span data-testid="me">{me ? `${me.name} · ${me.role}` : '…'}</span>
        {me?.role === 'support' && <a href="/admin/">Open admin</a>}
      </header>
      <Card title="Payments">
        {paymentsError ? (
          <p role="alert" style={{ color: tokens.color.bad, margin: 0 }}>Couldn’t load payments. Try again later.</p>
        ) : !payments ? (
          <p style={{ color: tokens.color.muted, margin: 0 }}>Loading payments…</p>
        ) : payments.length === 0 ? (
          <p style={{ color: tokens.color.muted, margin: 0 }}>No payments yet.</p>
        ) : (
        <ul data-testid="payments">
          {payments?.map((p) => (
            <li key={p.id} style={{ display: 'flex', alignItems: 'center', gap: tokens.space[2], padding: `${tokens.space[1]}px 0` }}>
              <span>
                {p.vendor}: ${p.amount}
              </span>
              {p.category && <Pill>{p.category}</Pill>}
            </li>
          ))}
        </ul>
      </Card>
    </main>
  );
}

createRoot(document.getElementById('root')!).render(
  <StagecraftRoot>
    <Dashboard />
  </StagecraftRoot>,
);

